<?php
namespace App\Controllers\Customer;
use App\Controllers\BaseController; use App\Libraries\Otp; use App\Libraries\Cart; use App\Models\UserModel;
class Auth extends BaseController { public function login(){ if($this->request->getMethod()==='POST'){ $email=strtolower(trim((string)$this->request->getPost('email'))); if(!filter_var($email,FILTER_VALIDATE_EMAIL))return redirect()->back()->withInput()->with('error','Enter a valid email address.'); $result=(new Otp())->send($email); if($result!==true)return redirect()->back()->with('error',$result); session()->set('otp_email',$email); return redirect()->to('/verify-otp'); } return view('customer/auth/login',['title'=>'Sign in']); } public function verify(){ $email=session('otp_email'); if(!$email)return redirect()->to('/login'); if($this->request->getMethod()==='POST'){ $code=(string)$this->request->getPost('otp'); if(!(new Otp())->verify($email,$code))return redirect()->back()->with('error','That code is invalid or expired.'); $users=new UserModel(); $user=$users->where('email',$email)->first(); if(!$user){$id=$users->insert(['email'=>$email],true);$user=$users->find($id);} (new Cart())->merge((int)$user['id']); session()->set(['customer_id'=>$user['id'],'customer_email'=>$email]); session()->remove('otp_email'); return redirect()->to('/'); } return view('customer/auth/verify',['title'=>'Verify your email','email'=>$email]); } public function logout(){ session()->remove(['customer_id','customer_email','otp_email']); session()->regenerate(true); return redirect()->to('/')->with('message','You have been signed out.'); } }
